const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Western Brazil polygon (approx bounds: longitude -75 to -50, latitude -20 to 0)
  const geometry = ee.Geometry.Polygon([
    [[-75, -20], [-75, 0], [-50, 0], [-50, -20]]
  ]);

  // August 2002
  const startDate2002 = '2002-08-01';
  const endDate2002 = '2002-08-31';

  // August 2018  
  const startDate2018 = '2018-08-01';
  const endDate2018 = '2018-08-31';

  // Function to get MODIS Terra AOD data
  function getMODIS_AOD(startDate, endDate, collectionName) {
    let collection = ee.ImageCollection(collectionName)
      .filterDate(startDate, endDate)
      .filterBounds(geometry);

    // Apply quality filter - only keep high quality retrievals (QA flag = 3 for best quality)
    // For MOD04_L2, 'Quality_Assurance_Land' band has quality flags
    // We'll mask pixels where QA != 3 (not the best quality)
    collection = collection.map(function(image) {
      const aod = image.select('Corrected_Optical_Depth_Land');
      const qa = image.select('Quality_Assurance_Land');
      // Mask where QA is not 3 (binary 11 = good quality)
      const mask = qa.eq(3);
      return aod.updateMask(mask).copyProperties(image, ['system:time_start']);
    });

    return collection;
  }

  // Try MODIS Terra first (MOD04_L2)
  let col2002 = getMODIS_AOD(startDate2002, endDate2002, 'MODIS/006/MOD04_L2');
  let col2018 = getMODIS_AOD(startDate2018, endDate2018, 'MODIS/006/MOD04_L2');

  // Check collection sizes
  const size2002 = col2002.size().getInfo();
  const size2018 = col2018.size().getInfo();

  console.log(`2002 August Images (Terra): ${size2002}`);
  console.log(`2018 August Images (Terra): ${size2018}`);

  // If empty, try MODIS Aqua (MYD04_L2) as fallback
  if (size2002 === 0) {
    console.log("Trying MODIS Aqua for 2002...");
    col2002 = getMODIS_AOD(startDate2002, endDate2002, 'MODIS/006/MYD04_L2');
    const newSize2002 = col2002.size().getInfo();
    console.log(`2002 August Images (Aqua): ${newSize2002}`);
    if (newSize2002 === 0) {
      console.log("<answer>C1</answer>");
      return;
    }
  }

  if (size2018 === 0) {
    console.log("Trying MODIS Aqua for 2018...");
    col2018 = getMODIS_AOD(startDate2018, endDate2018, 'MODIS/006/MYD04_L2');
    const newSize2018 = col2018.size().getInfo();
    console.log(`2018 August Images (Aqua): ${newSize2018}`);
    if (newSize2018 === 0) {
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // Create mean composite for each period
  const mean2002 = col2002.mean();
  const mean2018 = col2018.mean();

  // Calculate mean AOD and pixel count for each period
  const stats2002 = mean2002.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: geometry,
    scale: 10000,  // MODIS AOD is at 10km resolution
    maxPixels: 1e9,
    bestEffort: true
  }).getInfo();

  const stats2018 = mean2018.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: geometry,
    scale: 10000,
    maxPixels: 1e9,
    bestEffort: true
  }).getInfo();

  const meanAOD2002 = stats2002['Corrected_Optical_Depth_Land'];
  const count2002 = stats2002['Corrected_Optical_Depth_Land_count'];
  const meanAOD2018 = stats2018['Corrected_Optical_Depth_Land'];
  const count2018 = stats2018['Corrected_Optical_Depth_Land_count'];

  console.log(`2002 Mean AOD: ${meanAOD2002 ? meanAOD2002.toFixed(3) : 'null'}, Valid Pixels: ${count2002}`);
  console.log(`2018 Mean AOD: ${meanAOD2018 ? meanAOD2018.toFixed(3) : 'null'}, Valid Pixels: ${count2018}`);

  // Check for no valid pixels
  if (count2002 === 0 || count2018 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (meanAOD2002 === null || meanAOD2018 === null || 
      isNaN(meanAOD2002) || isNaN(meanAOD2018) ||
      meanAOD2002 < 0 || meanAOD2018 < 0) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if AOD decreased (2018 < 2002)
  if (meanAOD2018 < meanAOD2002) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
